/* ===== 8 TÍNH NĂNG BỔ SUNG ===== */
var X=X||{battles:[],orbDay:0,books:[],alloc:{}};
const PRIO=new Set([...DATA.teams[0].front,...DATA.teams[0].back]);
const SLOTN=s=>s>=15?8:s>=14?7:s>=12?6:s>=10?5:s>=9?3:s>=6?2:0;
const fmtN=v=>(+v||0).toLocaleString("vi-VN");
const daysFor=need=>X.orbDay>0&&need>0?Math.ceil(need/X.orbDay):null;
const dTxt=need=>{const d=daysFor(need);return d?` (~${d} ngày)`:""};

/* (1) Giữ nguyên liệu: tính sẵn tướng nào đang được giữ cho tướng PVP */
function reservedMap(){const m={};upPlan().forEach(p=>{if(PRIO.has(p.u.name)&&p.pick)p.pick.forEach(x=>{if(x.name!==p.u.name)m[x.id]=p.u.name})});return m}

/* (2) Lộ trình dài hạn */
function roadmap(name,target){
 const us=K.filter(u=>u.name===name).sort((a,b)=>b.star-a.star); if(!us.length) return null;
 const u=us[0], steps=[]; let copy=0, orb=0, unk=[]; const fod={};
 for(let s=u.star;s<target;s++){const R=RULE[s];
  if(!R||R.fs==null){unk.push(`${s}→${s+1}★`);steps.push({s,unk:true});continue}
  copy+=R.copy?1:0; if(R.orb==null)unk.push(`cầu cam ${s}→${s+1}★`); else orb+=R.orb;
  const k=`${u.phe} ${R.fs}★`; fod[k]=(fod[k]||0)+R.fc; steps.push({s,R});}
 const haveCopy=us.length-1;
 const fodHave=Object.fromEntries(Object.keys(fod).map(k=>{const st=+k.split(" ")[1].replace("★","");return [k,K.filter(x=>x.phe===u.phe&&x.name!==name&&x.r!=="SR"&&!CORE.has(x.name)&&x.star===st).length]}));
 // chi phí cầu cam để đẩy 1 tướng nguyên liệu từ 5★ lên mức sao yêu cầu (chỉ tính cầu cam)
 const raise=st=>{let o=0;for(let s=5;s<st;s++){const R=RULE[s];if(!R||R.orb==null)return null;o+=R.orb}return o};
 return {u,steps,copy,haveCopy,orb,fod,fodHave,unk,raise};
}
function renderRoad(){
 const el=document.getElementById("road"); if(!el) return;
 const names=bookHeroes().filter(n=>K.some(u=>u.name===n));
 const selN=document.getElementById("rdH"), selT=document.getElementById("rdT");
 const cur=selN&&names.includes(selN.value)?selN.value:names[0]; if(!cur){el.innerHTML='<p class="meta">Kho chưa có tướng đội chính.</p>';return}
 const st=Math.max(...K.filter(u=>u.name===cur).map(u=>u.star));
 let tg=selT?+selT.value:0; if(!(tg>st))tg=Math.min(15,Math.max(st+1,st<9?9:st<11?11:13));
 const r=roadmap(cur,tg);
 const fodRows=Object.entries(r.fod).map(([k,n])=>{const st2=+k.split(" ")[1].replace("★",""),h=r.fodHave[k],rc=r.raise(st2);
   return `<tr><td>Tướng ${esc(k)}</td><td class="num">${n}</td><td class="num ${h>=n?"ok":"bad"}">${h}</td><td>${h>=n?"Đủ":`Thiếu ${n-h}`}${st2>5&&h<n?` · nâng 1 tướng 5★ lên ${st2}★ tốn thêm ${rc==null?"? (có mốc chưa rõ)":fmtN(rc)+" cầu"} + bản trùng/nguyên liệu riêng`:""}</td></tr>`}).join("");
 const orbNeed=Math.max(0,r.orb-ORB);
 el.innerHTML=`<div class="khobar"><label for="rdH">Tướng</label><select id="rdH">${names.map(n=>`<option ${n===cur?"selected":""}>${esc(n)}</option>`).join("")}</select>
  <label for="rdT">Mục tiêu</label><select id="rdT">${Array.from({length:15-st},(_,i)=>st+1+i).map(s=>`<option value="${s}" ${s===tg?"selected":""}>${s}★</option>`).join("")}</select>
  <span class="meta">Hiện ${st}★ · ${SLOTN(st)} ô công pháp → ${SLOTN(tg)} ô</span></div>
  <div class="tablewrap" style="border:0"><table style="min-width:520px"><thead><tr><th>Cần</th><th>Tổng</th><th>Đang có</th><th>Tình trạng</th></tr></thead><tbody>
  <tr><td>Bản trùng ${esc(cur)}</td><td class="num">${r.copy}</td><td class="num ${r.haveCopy>=r.copy?"ok":"bad"}">${r.haveCopy}</td><td>${r.haveCopy>=r.copy?"Đủ":`Thiếu ${r.copy-r.haveCopy} – ưu tiên quay/đổi mảnh ${esc(cur)}`}</td></tr>
  ${fodRows}
  <tr><td>Cầu cam</td><td class="num">${fmtN(r.orb)}${r.unk.length?"+?":""}</td><td class="num ${ORB>=r.orb?"ok":"bad"}">${fmtN(ORB)}</td><td>${orbNeed?`Thiếu ${fmtN(orbNeed)}${dTxt(orbNeed)}`:"Đủ"}</td></tr>
  </tbody></table></div>
  ${r.unk.length?`<p class="meta">Chưa rõ yêu cầu: ${r.unk.join(", ")} – tổng ở trên chưa tính phần này.</p>`:""}
  <p class="meta">"Đang có" chỉ đếm tướng đúng mức sao, không tính tướng đội chính và tướng SR. Kiểm tra lại trong game trước khi nâng.</p>`;
}
document.addEventListener("change",e=>{if(e.target.id==="rdH"){const t=document.getElementById("rdT");if(t)t.value="";renderRoad()}else if(e.target.id==="rdT")renderRoad()});

/* (3) Nhập nhanh hàng loạt */
function heroInfo(n){const u=K.find(x=>x.name===n);if(u)return{phe:u.phe,r:u.r};if(byName[n])return{phe:byName[n].phe,r:"SSR+"};
 if(EDB[n])return{phe:EDB[n].phe,r:/SSR cam/.test(EDB[n].desc)?"SSR":/SR tím/.test(EDB[n].desc)?"SR":/R xanh/.test(EDB[n].desc)?"R":"SSR+"};return null}
function parseBulk(txt){const out=[],bad=[];
 txt.split(/[\n,;]+/).map(s=>s.trim()).filter(Boolean).forEach(s=>{
  let c=1,st=null; s=s.replace(/\s*[x×*]\s*(\d+)\s*$/i,(_,d)=>{c=+d;return""}).replace(/\s*(\d+)\s*(★|s|sao)\s*$/i,(_,d)=>{st=+d;return""}).replace(/\s*[x×*]\s*(\d+)\s*$/i,(_,d)=>{c=+d;return""}).trim();
  const all=[...new Set([...K.map(u=>u.name),...H.map(h=>h.name),...Object.keys(EDB)])];
  const nm=z=>z.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g,"").replace(/đ/g,"d").replace(/\s+/g," ");
  const n=all.find(a=>a.toLowerCase()===s.toLowerCase())||all.find(a=>nm(a)===nm(s));
  const inf=n&&heroInfo(n); if(!inf){bad.push(s);return}
  out.push({name:n,...inf,star:st||(inf.r==="SR"?4:inf.r==="R"?3:5),c:Math.max(1,Math.min(20,c))})});
 return {out,bad}}
function openBulk(){
 modal("Nhập nhanh nhiều tướng",`<p class="meta">Mỗi tướng cách nhau bằng dấu phẩy hoặc xuống dòng. Thêm <b>x2</b> cho số bản, <b>6★</b> (hoặc 6s) cho số sao. Gõ không dấu cũng được. Ví dụ:<br><code>Điển Vi x2, Tôn Thượng Hương, Lý Bạch 6★, tao nhan</code></p>
 <textarea id="bkT" rows="5" style="width:100%"></textarea><div id="bkP" class="meta" style="margin-top:6px"></div>`,()=>{
  const {out,bad}=parseBulk(document.getElementById("bkT").value);
  if(bad.length) return `Chưa biết phe/độ hiếm của: ${bad.join(", ")}. Thêm các tướng này bằng nút "Thêm tướng" trước.`;
  if(!out.length) return "Chưa nhập tướng nào.";
  snap(); out.forEach(o=>{for(let i=0;i<o.c;i++)K.push({id:nid(),name:o.name,phe:o.phe,star:o.star,r:o.r})});
  KLOG.push(`${today()} · Nhập nhanh: ${out.map(o=>`${o.c>1?o.c+" × ":""}${o.name} ${stars(o.star)}`).join(", ")}`); ksave();krender();syncHeroes();},"Thêm tất cả");
 const T=document.getElementById("bkT"),P=document.getElementById("bkP");
 T.addEventListener("input",()=>{const {out,bad}=parseBulk(T.value);P.innerHTML=out.map(o=>`✓ ${esc(o.name)} ${stars(o.star)} ${o.r}${o.c>1?" × "+o.c:""}`).join(" · ")+(bad.length?`<br><span style="color:#f0a35e">✗ ${bad.map(esc).join(", ")}</span>`:"")});T.focus();
}

