function logBattle(win){const en=VS.slots.map((s,i)=>({n:s.n,i,st:s.st||VS.st||"",lv:s.lv||"",tags:EDB[s.n]?EDB[s.n].tags:s.tags})).filter(s=>s.n);
 if(!en.length){alertBox("Nhập đội hình địch ở trên trước khi lưu trận.");return}
 X.battles.push({t:Date.now(),win,mode:document.getElementById("blMode").value,lv:+VS.lv||0,my:+LV||0,lcMe:parseLC(VS.lcMe),lcEn:parseLC(VS.lcEn),en,note:document.getElementById("blNote").value.trim(),r:+document.getElementById("blR").value||0,car:document.getElementById("blCar").value.trim()?parseLC(document.getElementById("blCar").value):null,stMe:parseLC(document.getElementById("blMe").value),stEn:parseLC(document.getElementById("blEn").value),per:(()=>{const g=p=>Array.from({length:6},(_,i)=>parseLC((document.querySelector(`[data-bls="${p}${i}"]`)||{}).value));const m=g("m"),e=g("e");return m.some(Boolean)||e.some(Boolean)?{me:m,en:e}:null})(),team:(()=>{const v=document.getElementById("blTeam").value;if(v==="vs"&&window.VSLAST)return {i:"vs",name:"Gợi ý Đối đầu",front:VSLAST.front.slice(),back:VSLAST.back.slice()};const ti=+v||0,t=DATA.teams[ti]||DATA.teams[0];return {i:ti,name:t.name,front:t.front.slice(),back:t.back.slice()}})()});
 ["blR","blCar","blMe","blEn"].forEach(id=>document.getElementById(id).value="");
 X.battles=X.battles.slice(-200);document.getElementById("blNote").value="";ksave();renderBattles()}
function alertBox(m){const o=document.getElementById("blMsg");if(o){o.textContent=m;setTimeout(()=>o.textContent="",4000)}}
function battleKind(b){const mx=/PVP/.test(b.mode)?20:15;if(/Rèn luyện/.test(b.mode))return b.stMe?`ST Boss ${fmtLC(b.stMe)}`:"";
 if(b.win)return b.r&&b.r>=mx-2?"Thắng sát nút (gần hết hiệp)":b.r&&b.r<=5?"Thắng áp đảo":"";
 if(b.r&&b.r>=mx)return "Hết hiệp – thiếu sát thương";
 if(b.car===0&&b.r)return "Carry bị khóa/hạ trước khi ra đòn";
 if(b.r&&b.r<=5)return "Bị dồn sát thương nhanh";
 if(b.stMe&&b.stEn&&b.stEn>b.stMe*2.5)return "Lệch sức mạnh (ST địch > 2,5× mình)";
 return b.r?"Thua giằng co":"";}
function renderBattles(){
 const bt=document.getElementById("blTeam");if(bt&&!bt.options.length){bt.innerHTML=DATA.teams.map((t,i)=>`<option value="${i}">Đội: ${esc(t.name)}</option>`).join("")}if(bt&&typeof curTeam!=="undefined"&&document.activeElement!==bt&&bt.value!=="vs")bt.value=String(curTeam);
 const el=document.getElementById("blList"); if(!el) return; const B=X.battles;
 const W=B.filter(b=>b.win&&!/Rèn luyện/.test(b.mode)).length,L=B.filter(b=>!b.win&&!/Rèn luyện/.test(b.mode)).length;
 const cnt=arr=>{const c={};arr.forEach(b=>new Set(b.en.flatMap(s=>s.tags||[])).forEach(t=>c[t]=(c[t]||0)+1));return c};
 const BB=B.filter(b=>!/Rèn luyện/.test(b.mode)),cl=cnt(BB.filter(b=>!b.win)),cw=cnt(BB.filter(b=>b.win));
 const tagRows=Object.keys(cl).map(t=>({t,l:cl[t],w:cw[t]||0})).filter(x=>x.l>=2).sort((a,b)=>(b.l/(b.l+b.w))-(a.l/(a.l+a.w))||b.l-a.l).slice(0,5);
 const gap=B.filter(b=>!b.win&&b.lv&&b.my&&b.lv-b.my>=10).length;
 el.innerHTML=`<p><b>${B.length}</b> trận · <span style="color:#5ec27a">${W} thắng</span> · <span style="color:#e0675a">${L} thua</span>${gap?` · ${gap} trận thua có chênh cấp ≥10`:""}</p>
 ${(()=>{const bg=B.filter(b=>/Rèn luyện/.test(b.mode)&&b.stMe);if(!bg.length)return "";const mx=Math.max(...bg.map(b=>b.stMe)),last=bg[bg.length-1].stMe;return `<p>Rèn luyện Bang: ${bg.length} lượt · cao nhất <b>${fmtLC(mx)}</b> · gần nhất ${fmtLC(last)}${bg.length>1?(last>=bg[bg.length-2].stMe?" ▲":" ▼"):""}</p>`})()}${(()=>{const k={};B.filter(b=>!b.win).forEach(b=>{const x=battleKind(b);if(x)k[x]=(k[x]||0)+1});const e=Object.entries(k).sort((a,b)=>b[1]-a[1]);return e.length?`<p class="meta">Kiểu thua:</p><ul>${e.map(([x,c])=>`<li><b>${esc(x)}</b> – ${c} trận</li>`).join("")}</ul>`:""})()}${tagRows.length?`<p class="meta">Hay thua trước đội có:</p><ul>${tagRows.map(x=>`<li><b>${TAGN[x.t]||x.t}</b> – thua ${x.l}/${x.l+x.w} trận gặp</li>`).join("")}</ul>`:(L?'<p class="meta">Cần thêm vài trận thua để thấy quy luật.</p>':"")}
 <ol class="klog" reversed>${B.slice().reverse().slice(0,30).map((b,k)=>`<li><span style="color:${b.win?"#5ec27a":"#e0675a"}">${b.win?"Thắng":"Thua"}</span> · ${esc(b.mode)} · ${new Date(b.t).toLocaleString("vi-VN",{day:"2-digit",month:"2-digit",hour:"2-digit",minute:"2-digit"})}${b.lv?` · địch Lv${b.lv}`:""}${b.my?` / mình Lv${b.my}`:""}${b.lcMe&&b.lcEn?` · LC ${fmtLC(b.lcMe)} vs ${fmtLC(b.lcEn)}`:""}${b.team?`<br><span class="meta">Mình: ${[...b.team.front,...b.team.back].map(esc).join(", ")}</span>`:""}<br><span class="meta">Địch: ${b.en.map(s=>`Ô${s.i+1} ${esc(s.n)}`).join(", ")}${b.note?" — "+esc(b.note):""}${b.r?` · ${b.r} hiệp`:""}${b.car!=null&&b.r?` · carry ${fmtLC(b.car)}`:""}${battleKind(b)?` · <b>${esc(battleKind(b))}</b>`:""}</span> <button class="btn ghost" data-blload="${b.t}" style="padding:2px 8px;font-size:12px">Nạp lại</button> <button class="btn ghost" data-bldel="${b.t}" style="padding:2px 8px;font-size:12px">✕</button></li>`).join("")}</ol>`;
}
document.addEventListener("click",e=>{const l=e.target.closest("[data-blload]"),d=e.target.closest("[data-bldel]");
 if(d){X.battles=X.battles.filter(b=>b.t!=d.dataset.bldel);ksave();renderBattles();return}
 if(l){const b=X.battles.find(x=>x.t==l.dataset.blload);if(!b)return;VS.slots=Array.from({length:6},(_,i)=>{const s=b.en.find(x=>x.i===i);return s?{n:s.n,tags:EDB[s.n]?[]:(s.tags||[])}:{n:"",tags:[]}});VS.lv=b.lv||"";vsSave();vsSlots();vsRun();window.scrollTo({top:0,behavior:"smooth"})}});

