function nextMile(h){const s=+h.sao||0,n=s+1,SL={6:2,9:3,10:5,12:6,14:7,15:8};let dt="";
 for(const m of [9,11,13]){if(s<m&&h["s"+m]){dt=`${m}★: ${h["s"+m]}`;break}} if(!dt&&s>=13&&h.nt)dt=`Nhập Thánh: ${h.nt}`;
 if(SL[n]&&!(dt&&dt.startsWith(n+"★"))){const sl=`${n}★: mở ô công pháp (${s>=6?(SL[s]||[...Object.entries(SL)].filter(([k])=>+k<=s).pop()[1]):0}→${SL[n]} ô)`;return dt?`${sl} · Đặc tính ${dt}`:sl}
 return dt}

