async function exportTeam(){
 const t=DATA.teams[curTeam],W=900,Hh=620,c=document.createElement("canvas");c.width=W;c.height=Hh;const g=c.getContext("2d");
 g.fillStyle="#14171d";g.fillRect(0,0,W,Hh);g.fillStyle="#f2e6c9";g.font="bold 30px Georgia,serif";g.fillText(t.name,32,52);
 g.font="15px sans-serif";g.fillStyle="#9aa3b2";g.fillText(`Sổ Tay Quân Sư${LV?" · Cấp chung "+LV:""} · ${new Date().toLocaleDateString("vi-VN")}`,32,80);
 const load=src=>new Promise(r=>{if(!src)return r(null);const i=new Image();i.onload=()=>r(i);i.onerror=()=>r(null);i.src=src});
 const rows=[["Hàng trước",t.front,120],["Hàng sau",t.back,360]];
 for(const [lab,arr,y] of rows){g.fillStyle="#9aa3b2";g.font="bold 14px sans-serif";g.fillText(lab.toUpperCase(),32,y);
  for(let i=0;i<arr.length;i++){const n=arr[i],x=32+i*285,yy=y+14,h=byName[n]||{};
   g.fillStyle="#1e232c";g.beginPath();g.roundRect?g.roundRect(x,yy,265,200,14):g.rect(x,yy,265,200);g.fill();
   const im=await load(ICONS[n]);g.save();g.beginPath();g.arc(x+60,yy+70,46,0,7);g.closePath();g.clip();if(im)g.drawImage(im,x+14,yy+24,92,92);else{g.fillStyle="#3a4252";g.fillRect(x+14,yy+24,92,92)}g.restore();
   const st=Math.max(0,...K.filter(u=>u.name===n).map(u=>u.star));
   g.fillStyle="#f2e6c9";let fs=20;do{g.font=`bold ${fs}px sans-serif`;fs--}while(g.measureText(n).width>132&&fs>11);g.fillText(n,x+122,yy+60);g.fillStyle="#e5b94e";g.font="bold 18px sans-serif";g.fillText(st?st+"★":"",x+122,yy+88);
   g.fillStyle="#9aa3b2";g.font="13px sans-serif";g.fillText(`Ô ${y===120?i+1:i+4} · ${h.phe||""}`,x+122,yy+112);
   const a=+(ATK||{})[n];if(a){g.fillText("Công "+fmtN(a),x+122,yy+134)}
   const why=(t.why[n]||"").replace(/^Ô \d+ – /,"");g.fillStyle="#c9cfd9";g.font="13px sans-serif";
   let line="",ly=yy+160;for(const w of why.split(" ")){if(g.measureText(line+w).width>235){g.fillText(line,x+16,ly);line="";ly+=18;if(ly>yy+196)break}line+=w+" "}if(ly<=yy+196)g.fillText(line,x+16,ly);}}
 const blob=await new Promise(r=>c.toBlob(r,"image/png"));const msg=document.getElementById("exMsg");
 try{const dl=window.claude&&window.claude.use?await window.claude.use("downloads"):null;
  if(dl){await dl.save({filename:`doi-hinh-${t.name.replace(/[^\p{L}\p{N}]+/gu,"-")}.png`,data:blob});msg.textContent="Đã lưu ảnh."}
  else{const a=document.createElement("a");a.href=URL.createObjectURL(blob);a.download="doi-hinh.png";a.click();msg.textContent="Đã tải ảnh."}}
 catch(e){msg.textContent=e&&e.code==="declined"?"Đã hủy lưu ảnh.":"Không lưu được ảnh trong chế độ xem này."}
 setTimeout(()=>msg.textContent="",4000);
}

