 const K1=Object.keys(P.keep).sort((a,b)=>P.own[b]-P.own[a]),K2=Object.keys(P.res).sort((a,b)=>P.own[b]-P.own[a]),K3=Object.keys(P.mat).sort((a,b)=>P.own[a]-P.own[b]);
 const card2=`<div class="panel"><h3>2. Tướng SSR+ giữ hay cho</h3>
  <div class="pgrp keep"><h4>Giữ & đầu tư (${K1.length})</h4><p class="meta">Có trong đội hiện tại hoặc đội lâu dài. Giữ <b>mọi bản trùng</b> – bản trùng là thứ hiếm nhất để lên 9★/11★/13★.</p><ul class="plist">${K1.map(n=>row(n,P.keep[n],"k")).join("")}</ul></div>
  <div class="pgrp res"><h4>Dự bị (${K2.length})</h4><p class="meta">Không vào đội nhưng có vai trò kho đang thiếu. Giữ 1 bản để đổi theo đối thủ; bản trùng dư có thể làm nguyên liệu.</p><ul class="plist">${K2.map(n=>row(n,P.res[n],"r")).join("")||'<li class="meta">Không có</li>'}</ul></div>
  <div class="pgrp mat"><h4>Dứt khoát làm nguyên liệu (${K3.length})</h4><p class="meta">Không vào đội nào, kể cả khi max sao. Dùng hết làm nguyên liệu nâng sao cùng phe cho nhóm Giữ.</p><ul class="plist">${K3.map(n=>row(n,P.mat[n],"m")).join("")||'<li class="meta">Không có</li>'}</ul></div>
  <p class="meta">SSR cam, SR, R luôn là nguyên liệu. Phân loại tự đổi khi bạn nâng sao, thêm tướng hoặc kho thay đổi.</p></div>`;
 const ups=upPlan().filter(p=>p.st==="ok").slice(0,4);
