const LP_TIER=["Lam","Tím","Cam","Đỏ","Vàng 1★","Vàng 2★","Vàng 3★","Đa Sắc 1★","Đa Sắc 2★","Đa Sắc 3★"];
const LP_VAL={HP:[7500,15000,30000,60000,75000,112500,150000,187500,225000,262500],"Công":[1000,2000,4000,8000,10000,15000,20000,25000,30000,35000],"Thủ":[250,500,1000,2000,2500,3750,5000,6250,7500,8800]};
const LP_BUFF=[0,0,0,0,5,10,15,20,25,30];
const LP_SLOTS={"Thanh Long":["HP","Công","Thủ","Tăng ST"],"Bạch Hổ":["HP","Công","Thủ","Giảm ST"],"Chu Tước":["HP","Công","Thủ","Tăng ST"],"Huyền Vũ":["HP","Công","Thủ","Giảm ST"]};
const LP_DEF={"Thanh Long":[1,2,0,-1],"Bạch Hổ":[0,1,0,-1],"Chu Tước":[-1,0,-1,-1],"Huyền Vũ":[0,-1,0,-1]};
function LPS(){X.lp=Object.assign(JSON.parse(JSON.stringify(LP_DEF)),X.lp||{});return X.lp}
function renderLinhPhu(){const g=document.getElementById("lpGrid");if(!g||!window.KREADY)return;const L=LPS();
 const tot={HP:0,"Công":0,"Thủ":0},buf={HP:0,"Công":0,"Thủ":0},empty=[];
 Object.entries(LP_SLOTS).forEach(([b,sl])=>sl.forEach((k,i)=>{const v=L[b][i];if(v<0){if(LP_VAL[k])empty.push(b+" – "+k);return}if(LP_VAL[k]){tot[k]+=LP_VAL[k][v];buf[k]+=LP_BUFF[v]}}));
 g.innerHTML=Object.entries(LP_SLOTS).map(([b,sl])=>`<div class="panel"><h3>${b}</h3>${sl.map((k,i)=>`<label class="lprow"><span>${k}</span><select data-lp="${b}|${i}"><option value="-1">— trống —</option>${LP_TIER.map((t,j)=>`<option value="${j}" ${L[b][i]===j?"selected":""}>${t}${LP_VAL[k]?" · +"+LP_VAL[k][j].toLocaleString("vi-VN")+(LP_BUFF[j]?" & "+LP_BUFF[j]+"%":""):""}</option>`).join("")}</select></label>`).join("")}</div>`).join("");
 const nx=Object.entries(LP_SLOTS).flatMap(([b,sl])=>sl.map((k,i)=>({b,k,v:L[b][i]}))).filter(x=>x.k==="Công"&&x.v>=0&&x.v<9).sort((a,c)=>a.v-c.v)[0];
 document.getElementById("lpTotal").innerHTML=`<h3>Tổng cộng cho mỗi tướng</h3><div class="radar-legend">${Object.keys(tot).map(k=>`<span>${k}: <b>+${tot[k].toLocaleString("vi-VN")}</b>${buf[k]?` & +${buf[k]}%`:""}</span>`).join("")}</div>
 ${empty.length?`<div class="warn" style="margin-top:8px">Ô trống nên lấp ngay (đeo phù Lam cũng có lợi): ${empty.map(esc).join(", ")}.</div>`:""}
 <p class="meta" style="margin-top:6px">Ưu tiên ghép: <b>Công</b> (tăng ST trực tiếp) &gt; HP &gt; Thủ.${nx?` Ô Công thấp nhất hiện tại: ${nx.b} (${LP_TIER[nx.v]}).`:""}</p>`}
